  if (o.doorY !== undefined) { taArchY(P, x + o.doorY - 4, y + d + 0.4, 0, (o.dw || 30) + 8, (o.dh || 58) + 6, tadd(tn, 'k2'), 0.7); taArchY(P, x + o.doorY, y + d + 0.6, 0, o.dw || 30, o.dh || 58, o.door || 'r5y4k4'); }
  if (o.doorX !== undefined) { taArchX(P, x + w + 0.4, y + o.doorX - 4, 0, (o.dw || 30) + 8, (o.dh || 58) + 6, tadd(tn, 'k2'), 0.7); taArchX(P, x + w + 0.6, y + o.doorX, 0, o.dw || 30, o.dh || 58, o.door || 'r5y4k4'); }
