  P.shape([T(-w / 2 + 6, -d / 2 + 3), T(w / 2 - 6, -d / 2 + 3), T(w / 2 - 6, d / 2 - 3), T(-w / 2 + 6, d / 2 - 3)], 'y1', 0.6);
  for (const s of [-1, 1]) { const a = T(s * (w / 2 - 4), -d / 2 + 1), b = T(s * (w / 2 - 4), d / 2 - 1); P.line([[a[0], a[1] - 3], [b[0], b[1] - 3]], 3.4, { ink: 1, lvl: 6, taper: 0 }); }
