  P.halo(c[0], c[1] - 20, r * 1.55, ['y1', 'y1b1', 'y2']);
  const band = P.ell(cx, cy, zt, r, r, 24, -Math.PI / 4, 3 * Math.PI / 4).concat(P.ell(cx, cy, z0, r, r, 24, 3 * Math.PI / 4, -Math.PI / 4));
  P.shape(band, 'y4r3k2', 1.2);
  P.fill(P.ell(cx, cy, z0 + 9, r, r, 24, -Math.PI / 4, 3 * Math.PI / 4).concat(P.ell(cx, cy, z0, r, r, 24, 3 * Math.PI / 4, -Math.PI / 4)), 'y4r4k4', { noKnock: true });
  P.line(P.ell(cx, cy, z0 + 17, r, r, 24, -Math.PI / 4, 3 * Math.PI / 4), 0.6);
  for (let i = 0; i < 9; i++) { const a = -Math.PI / 4 + (i + 0.5) * Math.PI / 9, p = P.I(cx + Math.cos(a) * r, cy + Math.sin(a) * r, z0); P.line([p, [p[0] + 2, p[1] + 8 + (i % 3) * 5], [p[0] - 1, p[1] + 14 + (i % 2) * 6]], 0.6); }
  P.shape(P.ell(cx, cy, zt, r, r, 44), 'y5b4', 1.3);
  P.shape(P.ell(cx + 42, cy - 48, zt + 0.3, 58, 42, 26), 'b5y1', 0.8);
  for (let i = 0; i < 7; i++) { const q = P.I(cx + 20 + (i % 3) * 20, cy - 70 + i * 8, zt); P.line([[q[0] - 6, q[1]], [q[0] - 2, q[1] - 2], [q[0] + 2, q[1]], [q[0] + 6, q[1] - 2]], 0.5, { ink: 2 }); }
  const hill = (x, y, w, hh, tn) => { const b = P.I(x, y, zt); P.shape(smooth([[b[0] - w, b[1]], [b[0] - w * 0.4, b[1] - hh * 0.8], [b[0], b[1] - hh], [b[0] + w * 0.5, b[1] - hh * 0.6], [b[0] + w, b[1]]], 3), tn, 0.9); P.line([[b[0], b[1] - hh], [b[0] + w * 0.2, b[1] - hh * 0.4], [b[0] + w * 0.1, b[1]]], 0.6); };
