  for (const [a, b, w, hh, tn] of [[-10, 0, 18, 18, 'y3r2'], [8, 12, 14, 14, 'y4r3k1'], [-24, 20, 16, 20, 'y3r2k1'], [4, 34, 18, 12, 'y4r2']]) P.box(cx + a, cy + b, zt, w, 14, hh, tn, 0.6);
